{
  "$schema": "https://opencode.ai/config.json",
  "command": {
    "telegram": {
      "template": "Call the telegram_control tool with action set to \"$ARGUMENTS\". If $ARGUMENTS is empty, use \"on\" as the default action.",
      "description": "Toggle Telegram bridge mode (on/off/status)"
    }
  }
}

{
  "name": "opencode-chat",
  "version": "1.0.0",
  "description": "Telegram bridge plugin for OpenCode — receive notifications and respond to your AI agent from Telegram",
  "main": "src/index.ts",
  "type": "module",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "telegram",
    "bridge",
    "notifications"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/sasasalamon/opencode-chat"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  }
}
